# ---------------------------------------------------------------------------
# Region Details module test data
#
# IMPORTANT: Region IDs (e.g. "G150") are auto-generated by the server and
# change whenever regions are created or deleted. No ID is stored here.
# Regions are identified by NAME only; the ID is read from the Coverage tree
# at runtime (see RegionDetailsModal.get_region_id_from_tree).
#
# Two kinds of names live here:
#   * FIXED names  - shared regions. Tests call _ensure_region(), which
#                    creates the region only if it is not already in the tree.
#   * *_BASE names - prefixes only. The test appends a suffix with
#                    utils.helpers.unique() so every run creates a brand-new
#                    region and re-runs never collide with old data.
# ---------------------------------------------------------------------------

MODAL_TITLE = "Region Details"
EDIT_MODAL_TITLE = "Catalog - Edit Region"

# ---------------------------------------------------------------------------
# Shared regions (created only if missing)
# ---------------------------------------------------------------------------
# Primary region used by most tests.
PRIMARY_REGION_NAME = "Region_Detail_Test"

# TC_007: two sibling regions - the details must belong to the clicked one.
PATH_TEST_REGION_1_NAME = "Region_Detail_Path_Test 1"
PATH_TEST_REGION_2_NAME = "Region_Detail_Path_Test 2"

# TC_016: region deleted from another session.
DELETE_TEST_REGION_NAME = "Region_Detail_Delete_Test"

# TC_021: second region used to prove the modal is not cached.
FRESH_REGION_NAME = "Region_Detail_Fresh_Test"

# TC_023: region that never has a network created under it.
NO_NETWORK_REGION_NAME = "Region_Detail_No_Network_Test"

# TC_011: 255-character name. The tree row is truncated with "...", so the
# row is located by the first LONG_NAME_TREE_PREFIX_LENGTH characters.
LONG_NAME_REGION_NAME = "M" * 255
LONG_NAME_TREE_PREFIX = "M" * 8

# TC_012: single-character name (cannot be made unique).
SHORT_NAME_REGION_NAME = "R"

# ---------------------------------------------------------------------------
# Prefixes for regions created fresh on every run (unique() suffix added)
# ---------------------------------------------------------------------------
# TC_010: two regions sharing an identical Label (suffix is shared by both).
DUPLICATE_LABEL_REGION_BASE = "Region_Detail_Duplicate_Test"

# TC_013 / TC_029: injection payloads.
SCRIPT_INJECTION_REGION_BASE = "<script>alert(1)</script>"
SQL_INJECTION_REGION_BASE = "' OR '1'='1"

# TC_014: whitespace trimming (entered with 1 leading + 1 trailing space).
TRIMMED_REGION_BASE = "Trimmed Test Region"

# ---------------------------------------------------------------------------
# Keyboard input used to verify the read-only fields reject typing (TC_027)
# ---------------------------------------------------------------------------
READ_ONLY_FIELD_TYPED_INPUT = "abc123"

# Viewports (TC_025 / TC_026)
MOBILE_VIEWPORT = {"width": 375, "height": 812}
DESKTOP_VIEWPORT = {"width": 1920, "height": 1080}
SMALL_DESKTOP_VIEWPORT = {"width": 800, "height": 600}

# Coverage area section (TC_001 / TC_028)
NO_POLYGON_TEXT = "No coverage polygon defined."